dir$s334.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir, g = p.grid(0), dt = g.data;
  switch (id) {
    case 'ok':
		var d = p.valForm('ngay_hl'),d2 = p.valForm('ngay_hld');
		var k = $.date(d,"dd/mm/yy"),k2 = $.date(d2,"dd/mm/yy");
		if (p.valForm('ngay_hld') <= p.valForm('ngay_hl')) { 
			<!-- $.showToast(p.msg('noDate')); -->
			<!-- $.question('jkhj '+'Nhap sai ngay ??' ); -->

			$.alert(p.msg('noDate')+' ' + k + ' < ' + k2);			
			return false;
			Break;
			}	  		  
    default:
      break;
  }
  return true;
}
dir$s334.prototype.beforeButtonGridClick = function (id, gindex) {
  var p = this._dir;
  switch (id) {
    default:
      break;
  }
  return true;
}

dir$s334.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$s334HiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$s334HiddenColumnByType(p);
      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
	  p.calcExpressionAll(1, '!ty_gia');
      break;
    case 'ma_kh':
      p.request('Customer', '', ['ma_kh', 'ngay_ct', 'ma_nt']);
      break;
	case 'ma_dk_ngay':
      dir$s334HiddenColumnByDay(p);
      break;
    default:
      break;
  }
}
&VoucherExRateValid02;
dir$s334.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$s334DisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$s334DisabledMasterField(p, g){
if ( p.options.action != 'NEW')
